var t=`1327-ceviche-peruano`;var o=`world-1327`;var n=`PE`;var a=`south-america`;var r=4;var s=77;var d={en:`Ceviche Peruano`,ua:`Перуанське севіче`};var l={en:`Ceviche Peruano is a dish from Peru featuring sea bass, sweet potato, sweet corn, red onion. This home-sized recipe records each ingredient at the step where it is used. Food-safety adaptation: fish is heat-cooked before dressing; traditional Peruvian ceviche commonly uses raw fish. Citrus alone is not a safety substitute.`,ua:`Перуанське севіче, страва кухні країни Перу з такими основними складниками: сібас, батат, солодка кукурудза, червона цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання. Адаптація для безпеки: рибу термічно готують перед цитрусовою заправкою; традиційне перуанське севіче зазвичай із сирої риби. Цитрус не замінює термічну обробку.`};var c=[{en:`For this heat-cooked adaptation, cook fish to 63°C or fully opaque, then cool promptly before the lime dressing.`,ua:`Для цієї термічно обробленої версії приготуйте рибу до 63°C чи повної непрозорості, потім швидко охолодіть перед лаймовою заправкою.`,t:[`poaching`],m:12,i:[[`sea-bass`,700,`g`],[`water`,650,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 22 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 22 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:22,i:[[`sweet-potato`,330,`g`],[`sweet-corn`,2,`pcs`],[`water`,800,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`red-onion`,200,`g`],[`cilantro`,30,`g`],[`serrano-pepper`,2,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`lime-juice`,170,`ml`],[`table-salt`,7,`g`],[`aji-amarillo-paste`,20,`g`]]},{en:`Refrigerate the prepared mixture for about 22 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 22 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:22,i:[]},{en:`Arrange the fully cooked and prepared parts of the dish on plates or in the intended serving vessel, adding the listed toppings or accompaniments just before serving.`,ua:`Зберіть повністю приготовані частини страви на тарілках або в посуді для подавання, додавши зазначені топінги та доповнення безпосередньо перед подаванням.`,t:[`layered-assembly`,`garnishing`],m:5,i:[]}];var p={slug:t,id:o,country:`PE`,region:a,servings:4,minutes:77,title:d,text:l,steps:c};export{n as country,p as default,o as id,s as minutes,a as region,r as servings,t as slug,c as steps,l as text,d as title};